def fill_hollow_regions(grid):
    """Fill hollow 8-regions with 9s"""
    h, w = grid.shape
    result = grid.copy()

    # For each 0 that has 4+ 8 neighbors, it's inside a shape
    for r in range(1, h-1):
        for c in range(1, w-1):
            if grid[r, c] == 0:
                count_8 = sum(1 for dr in [-1, 0, 1] for dc in [-1, 0, 1] 
                             if not (dr == 0 and dc == 0) and grid[r+dr, c+dc] == 8)
                if count_8 >= 4:
                    result[r, c] = 9

    return result

